-- =============================================================================
-- ABCRM — Phase 0–1 database schema (PostgreSQL 17+)
-- Migration 0001. Copied from docs/specs/phase-0-1/schema.sql (spec v0.1). From now on this file and later
-- migrations are the source of truth; the spec links here.
--
-- Conventions
--   * IDs: UUIDv7 generated by the application (time-ordered). No DB default.
--   * Every tenant-scoped table has tenant_id uuid NOT NULL and RLS FORCED.
--   * PII columns end with _enc (bytea, AES-256-GCM with tenant DEK, app-level).
--     Exact-match lookups use *_bidx (bytea, HMAC-SHA256 with tenant BIDX key).
--     Global (cross-tenant) lookups use *_ghmac (HMAC with platform global key).
--   * Timestamps are timestamptz, UTC.
--   * Enums are TEXT + CHECK (easier migrations than PG enums).
--   * Append-only tables: REVOKE UPDATE, DELETE from app roles.
--
-- Roles
--   abcrm_migrator : owns schema, runs migrations (BYPASSRLS).
--   abcrm_app      : app + worker for tenant-scoped work (NO BYPASSRLS).
--   abcrm_global   : worker-only role for global tables (public_pages,
--                    licensed_contact_cache, global_*). Never used in request path.
--
-- Session context (set per transaction by the app, transaction-local):
--   SELECT set_config('app.tenant_id', '<uuid>', true);
--   SELECT set_config('app.actor', '<user:uuid|agent:run_uuid|system>', true);
-- =============================================================================

CREATE SCHEMA IF NOT EXISTS abcrm;
SET search_path = abcrm, public;

-- pgvector is required in staging/prod (pgvector/pgvector:pg17 image, Neon). Phase 0–1 tables do not use it yet,
-- so local clusters without the extension still migrate.
DO $$ BEGIN
  CREATE EXTENSION IF NOT EXISTS vector;
EXCEPTION WHEN undefined_file OR feature_not_supported THEN
  RAISE NOTICE 'pgvector not available on this cluster; skipping';
END $$;
CREATE EXTENSION IF NOT EXISTS pg_trgm;    -- fuzzy company-name search

-- -----------------------------------------------------------------------------
-- Helpers
-- -----------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION current_tenant_id() RETURNS uuid
LANGUAGE sql STABLE AS $$
  SELECT nullif(current_setting('app.tenant_id', true), '')::uuid
$$;

CREATE OR REPLACE FUNCTION touch_updated_at() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN NEW.updated_at := now(); RETURN NEW; END $$;

-- Applies standard tenant isolation policy + updated_at trigger to a table.
CREATE OR REPLACE FUNCTION enable_tenant_rls(tbl regclass, has_updated_at boolean DEFAULT true)
RETURNS void LANGUAGE plpgsql AS $$
BEGIN
  EXECUTE format('ALTER TABLE %s ENABLE ROW LEVEL SECURITY', tbl);
  EXECUTE format('ALTER TABLE %s FORCE ROW LEVEL SECURITY', tbl);
  EXECUTE format($p$CREATE POLICY tenant_isolation ON %s
                    USING (tenant_id = current_tenant_id())
                    WITH CHECK (tenant_id = current_tenant_id())$p$, tbl);
  IF has_updated_at THEN
    EXECUTE format('CREATE TRIGGER trg_touch BEFORE UPDATE ON %s
                    FOR EACH ROW EXECUTE FUNCTION touch_updated_at()', tbl);
  END IF;
END $$;

-- =============================================================================
-- 1. PLATFORM / IAM
-- =============================================================================

-- Plans & entitlements (global, read-only for app)
CREATE TABLE plan_entitlements (
  plan                     text PRIMARY KEY CHECK (plan IN ('trial','starter','growth','scale','enterprise')),
  template_keys            text[] NOT NULL,
  included_agent_credits   int    NOT NULL,
  included_contact_credits int    NOT NULL,
  max_concurrency          int    NOT NULL,
  max_active_monitors      int    NOT NULL,
  max_mailboxes            int    NOT NULL,
  min_poll_interval        interval NOT NULL,
  max_model_tier           text   NOT NULL CHECK (max_model_tier IN ('small','medium','large')),
  overage_default          boolean NOT NULL,
  spend_cap_default_pct    int    NOT NULL DEFAULT 50,
  updated_at               timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE tenants (
  id                uuid PRIMARY KEY,
  name              text NOT NULL,
  slug              text NOT NULL UNIQUE,
  region            text NOT NULL DEFAULT 'us' CHECK (region IN ('us')),   -- ADR-010 deferred
  country           text,                                                  -- ISO-3166 of agency HQ (VN, PH, IN…)
  workos_org_id     text UNIQUE,
  stripe_customer_id text UNIQUE,
  plan              text NOT NULL DEFAULT 'trial' REFERENCES plan_entitlements(plan),
  status            text NOT NULL DEFAULT 'active' CHECK (status IN ('active','suspended','killed','deleted')),
  kill_switch       boolean NOT NULL DEFAULT false,      -- FR-A10: stops all agent runs immediately
  postal_address    jsonb,                               -- CAN-SPAM footer (Phase 2)
  settings          jsonb NOT NULL DEFAULT '{}',
  created_at        timestamptz NOT NULL DEFAULT now(),
  updated_at        timestamptz NOT NULL DEFAULT now()
);
-- tenants is not RLS-filtered by tenant_id column name; use id.
ALTER TABLE tenants ENABLE ROW LEVEL SECURITY;
ALTER TABLE tenants FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_self ON tenants USING (id = current_tenant_id()) WITH CHECK (id = current_tenant_id());
CREATE TRIGGER trg_touch BEFORE UPDATE ON tenants FOR EACH ROW EXECUTE FUNCTION touch_updated_at();

-- Per-tenant wrapped data keys (envelope encryption via KMS)
CREATE TABLE tenant_keys (
  tenant_id     uuid NOT NULL REFERENCES tenants(id),
  key_version   int  NOT NULL,
  purpose       text NOT NULL CHECK (purpose IN ('dek','bidx')),
  wrapped_key   bytea NOT NULL,               -- encrypted by KMS CMK
  kms_key_ref   text NOT NULL,
  status        text NOT NULL DEFAULT 'active' CHECK (status IN ('active','retired','destroyed')),
  created_at    timestamptz NOT NULL DEFAULT now(),
  updated_at    timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (tenant_id, purpose, key_version)
);
SELECT enable_tenant_rls('tenant_keys');

CREATE TABLE users (
  id                 uuid PRIMARY KEY,
  tenant_id          uuid NOT NULL REFERENCES tenants(id),
  workos_user_id     text NOT NULL,
  email              text NOT NULL,              -- staff email (not prospect PII)
  name               text,
  role               text NOT NULL CHECK (role IN ('owner','admin','head_of_bd','sales_rep','viewer')),
  timezone           text NOT NULL DEFAULT 'Asia/Ho_Chi_Minh',   -- IANA
  working_hours      jsonb NOT NULL DEFAULT '{"mon-fri":["08:30","17:30"]}',
  locale             text NOT NULL DEFAULT 'en' CHECK (locale IN ('en','vi')),
  status             text NOT NULL DEFAULT 'active' CHECK (status IN ('invited','active','disabled')),
  created_at         timestamptz NOT NULL DEFAULT now(),
  updated_at         timestamptz NOT NULL DEFAULT now(),
  UNIQUE (tenant_id, workos_user_id),
  UNIQUE (tenant_id, email)
);
SELECT enable_tenant_rls('users');

-- Service personas: identities agents act on behalf of (ADR-003)
CREATE TABLE service_personas (
  id          uuid PRIMARY KEY,
  tenant_id   uuid NOT NULL REFERENCES tenants(id),
  key         text NOT NULL,                     -- e.g. 'sourcing', 'qualification'
  permissions text[] NOT NULL,                   -- permission strings, see tools.md
  created_by  uuid REFERENCES users(id),
  created_at  timestamptz NOT NULL DEFAULT now(),
  updated_at  timestamptz NOT NULL DEFAULT now(),
  UNIQUE (tenant_id, key)
);
SELECT enable_tenant_rls('service_personas');

CREATE TABLE api_keys (
  id          uuid PRIMARY KEY,
  tenant_id   uuid NOT NULL REFERENCES tenants(id),
  name        text NOT NULL,
  key_prefix  text NOT NULL,                     -- shown in UI, e.g. 'abk_live_3f9a'
  key_hash    bytea NOT NULL UNIQUE,             -- SHA-256 of full key
  scopes      text[] NOT NULL,
  created_by  uuid REFERENCES users(id),
  last_used_at timestamptz,
  revoked_at  timestamptz,
  created_at  timestamptz NOT NULL DEFAULT now(),
  updated_at  timestamptz NOT NULL DEFAULT now()
);
SELECT enable_tenant_rls('api_keys');

-- =============================================================================
-- 2. SUPPLY PROFILE, IPP, PLAYBOOK
-- =============================================================================

CREATE TABLE supply_profiles (
  id                uuid PRIMARY KEY,
  tenant_id         uuid NOT NULL REFERENCES tenants(id),
  version           int  NOT NULL,
  status            text NOT NULL CHECK (status IN ('draft','pending_approval','active','archived')),
  verticals         text[] NOT NULL,                          -- insurance|finance|home_services|education|legal
  lead_types        jsonb NOT NULL,                           -- [{vertical, type, formats:[data_lead,...], delivery:[ping_post,direct_post,batch]}]
  traffic_sources   text[] NOT NULL DEFAULT '{}',
  daily_capacity    jsonb NOT NULL DEFAULT '{}',              -- {lead_type: n}
  states            text[] NOT NULL DEFAULT '{}',             -- US state codes covered
  compliance_assets jsonb NOT NULL DEFAULT '{}',              -- {trustedform:true, jornaya:false, consent_language_url, dnc_scrub:true}
  positioning       text,
  docs              jsonb NOT NULL DEFAULT '[]',              -- [{kind: rate_card|case_study|compliance_pack, object_ref, title}]
  approved_decision_id uuid,
  created_by        uuid REFERENCES users(id),
  created_at        timestamptz NOT NULL DEFAULT now(),
  updated_at        timestamptz NOT NULL DEFAULT now(),
  UNIQUE (tenant_id, version)
);
SELECT enable_tenant_rls('supply_profiles');
CREATE UNIQUE INDEX one_active_supply_profile ON supply_profiles (tenant_id) WHERE status = 'active';

CREATE TABLE playbooks (
  id              uuid PRIMARY KEY,
  tenant_id       uuid NOT NULL REFERENCES tenants(id),
  lineage_id      uuid NOT NULL,                 -- same across versions
  name            text NOT NULL,
  version         int  NOT NULL,
  status          text NOT NULL CHECK (status IN ('draft','pending_approval','active','archived')),
  vertical_pack   text,                          -- e.g. 'insurance@1' (template origin)
  tier_thresholds jsonb NOT NULL DEFAULT '{"A":75,"B":55,"C":35}',
  card_min_tier   text NOT NULL DEFAULT 'B' CHECK (card_min_tier IN ('A','B','C')),
  definition_hash text NOT NULL,                 -- hash of criteria set (immutability check)
  approved_decision_id uuid,
  created_by      uuid REFERENCES users(id),
  created_at      timestamptz NOT NULL DEFAULT now(),
  updated_at      timestamptz NOT NULL DEFAULT now(),
  UNIQUE (tenant_id, lineage_id, version)
);
SELECT enable_tenant_rls('playbooks');

CREATE TABLE criteria (
  id                uuid PRIMARY KEY,
  tenant_id         uuid NOT NULL REFERENCES tenants(id),
  playbook_id       uuid NOT NULL REFERENCES playbooks(id),
  key               text NOT NULL,               -- stable within lineage, e.g. 'buys_data_leads'
  name              text NOT NULL,
  description       text NOT NULL,
  kind              text NOT NULL CHECK (kind IN ('knockout','must_have','scored')),
  evaluation        text NOT NULL CHECK (evaluation IN ('rule','ai_judged')),
  rule              jsonb,                       -- JSONLogic when evaluation='rule'
  weight            int  NOT NULL DEFAULT 0 CHECK (weight BETWEEN 0 AND 100),
  evidence_required boolean NOT NULL DEFAULT true,
  unknown_policy    text NOT NULL DEFAULT 'neutral' CHECK (unknown_policy IN ('neutral','penalize','block')),
  unknown_penalty   int  NOT NULL DEFAULT 0,
  hints             text[] NOT NULL DEFAULT '{}',
  order_no          int  NOT NULL,
  created_at        timestamptz NOT NULL DEFAULT now(),
  updated_at        timestamptz NOT NULL DEFAULT now(),
  UNIQUE (playbook_id, key),
  CHECK ((evaluation = 'rule') = (rule IS NOT NULL))
);
SELECT enable_tenant_rls('criteria');
-- Criteria of a non-draft playbook are immutable (enforced in app + trigger).
CREATE OR REPLACE FUNCTION criteria_immutable() RETURNS trigger LANGUAGE plpgsql
SET search_path = abcrm, pg_temp AS $$
BEGIN
  IF (SELECT status FROM playbooks WHERE id = COALESCE(NEW.playbook_id, OLD.playbook_id)) <> 'draft' THEN
    RAISE EXCEPTION 'criteria of a non-draft playbook are immutable';
  END IF;
  RETURN COALESCE(NEW, OLD);
END $$;
CREATE TRIGGER trg_criteria_immutable BEFORE INSERT OR UPDATE OR DELETE ON criteria
  FOR EACH ROW EXECUTE FUNCTION criteria_immutable();

CREATE TABLE ipps (
  id               uuid PRIMARY KEY,
  tenant_id        uuid NOT NULL REFERENCES tenants(id),
  lineage_id       uuid NOT NULL,
  name             text NOT NULL,
  version          int  NOT NULL,
  status           text NOT NULL CHECK (status IN ('draft','pending_approval','active','archived')),
  vertical         text NOT NULL,
  lead_types       text[] NOT NULL,
  buyer_types      text[] NOT NULL,              -- direct_brand|aggregator|affiliate_network|ping_post_exchange|call_buyer
  purchase_formats text[] NOT NULL DEFAULT '{data_lead}',
  payout_models    text[] NOT NULL DEFAULT '{cpl}',
  size             jsonb NOT NULL DEFAULT '{}',  -- {employees_min, employees_max, states_min}
  signals          jsonb NOT NULL DEFAULT '{}',  -- {web_paths:[], tech:[], text:[]}
  exclusions       jsonb NOT NULL DEFAULT '{}',  -- {domains:[], keywords:[], buyer_types:[]}
  contact_titles   text[] NOT NULL,
  contacts_per_account int NOT NULL DEFAULT 2 CHECK (contacts_per_account BETWEEN 1 AND 5),
  playbook_id      uuid NOT NULL REFERENCES playbooks(id),
  approved_decision_id uuid,
  created_by       uuid REFERENCES users(id),
  created_at       timestamptz NOT NULL DEFAULT now(),
  updated_at       timestamptz NOT NULL DEFAULT now(),
  UNIQUE (tenant_id, lineage_id, version)
);
SELECT enable_tenant_rls('ipps');

-- =============================================================================
-- 3. CRM CORE (pipeline minimal)
-- =============================================================================

CREATE TABLE accounts (
  id              uuid PRIMARY KEY,
  tenant_id       uuid NOT NULL REFERENCES tenants(id),
  name            text NOT NULL,
  domain          text NOT NULL,                 -- normalized registrable domain (eTLD+1), lowercase
  domain_bidx     bytea NOT NULL,
  buyer_type      text,
  verticals       text[] NOT NULL DEFAULT '{}',
  lead_types      text[] NOT NULL DEFAULT '{}',
  hq_state        text,
  hq_country      text,
  employee_range  text,
  founded_year    int,
  tech_signals    jsonb NOT NULL DEFAULT '{}',   -- {trustedform:{seen_at,url}, leadspedia:{...}}
  status          text NOT NULL DEFAULT 'prospect'
                  CHECK (status IN ('prospect','carded','approved','contacted','engaged','opportunity','partner','lost','blocked')),
  flags           text[] NOT NULL DEFAULT '{}',  -- competitor|existing_buyer|do_not_contact
  owner_user_id   uuid REFERENCES users(id),
  custom          jsonb NOT NULL DEFAULT '{}',
  last_contacted_at timestamptz,
  created_at      timestamptz NOT NULL DEFAULT now(),
  updated_at      timestamptz NOT NULL DEFAULT now(),
  UNIQUE (tenant_id, domain_bidx)
);
SELECT enable_tenant_rls('accounts');
CREATE INDEX accounts_name_trgm ON accounts USING gin (name gin_trgm_ops);
CREATE INDEX accounts_status ON accounts (tenant_id, status);

CREATE TABLE contacts (
  id                  uuid PRIMARY KEY,
  tenant_id           uuid NOT NULL REFERENCES tenants(id),
  account_id          uuid NOT NULL REFERENCES accounts(id),
  first_name_enc      bytea,
  last_name_enc       bytea,
  title               text,
  title_normalized    text,                      -- e.g. 'affiliate_manager', 'partnerships_director'
  seniority           text CHECK (seniority IN ('ic','manager','director','vp','c_level','owner')),
  email_enc           bytea,
  email_bidx          bytea,
  email_verification  jsonb,                     -- {provider, result: valid|catch_all|invalid|unknown, checked_at}
  phone_enc           bytea,                     -- only if tenant-imported (D26)
  linkedin_url        text,                      -- from provider or import only; never scraped (D26)
  timezone            text,
  source              jsonb NOT NULL,            -- {kind: provider|import|manual|referral, provider?, import_job_id?, acquired_at, license_ref?}
  status              text NOT NULL DEFAULT 'active' CHECK (status IN ('active','suppressed','suppressed_by_source','deleted')),
  created_at          timestamptz NOT NULL DEFAULT now(),
  updated_at          timestamptz NOT NULL DEFAULT now()
);
SELECT enable_tenant_rls('contacts');
CREATE UNIQUE INDEX contacts_email_unique ON contacts (tenant_id, email_bidx) WHERE email_bidx IS NOT NULL;
CREATE INDEX contacts_account ON contacts (tenant_id, account_id);

CREATE TABLE opportunities (
  id             uuid PRIMARY KEY,
  tenant_id      uuid NOT NULL REFERENCES tenants(id),
  account_id     uuid NOT NULL REFERENCES accounts(id),
  stage          text NOT NULL DEFAULT 'engaged'
                 CHECK (stage IN ('engaged','meeting','negotiation','test','won','lost')),
  owner_user_id  uuid REFERENCES users(id),
  expected_monthly_value numeric(12,2),
  next_step      text,
  close_date     date,
  lost_reason    text,
  created_at     timestamptz NOT NULL DEFAULT now(),
  updated_at     timestamptz NOT NULL DEFAULT now()
);
SELECT enable_tenant_rls('opportunities');

CREATE TABLE activities (
  id           uuid PRIMARY KEY,
  tenant_id    uuid NOT NULL REFERENCES tenants(id),
  account_id   uuid REFERENCES accounts(id),
  contact_id   uuid REFERENCES contacts(id),
  kind         text NOT NULL CHECK (kind IN ('note','task','call','meeting','email','system')),
  body         text,
  due_at       timestamptz,
  done_at      timestamptz,
  actor        jsonb NOT NULL,                  -- {type:user|agent|system, id}
  created_at   timestamptz NOT NULL DEFAULT now(),
  updated_at   timestamptz NOT NULL DEFAULT now()
);
SELECT enable_tenant_rls('activities');
CREATE INDEX activities_account ON activities (tenant_id, account_id, created_at DESC);

-- Tenant-level suppression / blocklist (email, domain, account)
CREATE TABLE suppression_entries (
  id          uuid PRIMARY KEY,
  tenant_id   uuid NOT NULL REFERENCES tenants(id),
  kind        text NOT NULL CHECK (kind IN ('email','domain')),
  value_bidx  bytea NOT NULL,
  reason      text NOT NULL CHECK (reason IN ('unsubscribe','bounce','complaint','dsar','manual','competitor','existing_buyer','import')),
  source      jsonb NOT NULL DEFAULT '{}',
  created_by  jsonb NOT NULL,
  created_at  timestamptz NOT NULL DEFAULT now(),
  UNIQUE (tenant_id, kind, value_bidx)
);
SELECT enable_tenant_rls('suppression_entries', false);

-- =============================================================================
-- 4. SOURCING
-- =============================================================================

CREATE TABLE sourcing_runs (
  id                     uuid PRIMARY KEY,
  tenant_id              uuid NOT NULL REFERENCES tenants(id),
  ipp_id                 uuid NOT NULL REFERENCES ipps(id),
  agent_definition_id    uuid,
  target_count           int  NOT NULL CHECK (target_count BETWEEN 1 AND 5000),
  agent_credit_budget    int  NOT NULL,
  contact_credit_budget  int  NOT NULL,
  status                 text NOT NULL DEFAULT 'pending_approval'
                         CHECK (status IN ('pending_approval','queued','running','paused','budget_exhausted','completed','cancelled','failed')),
  plan                   jsonb,                 -- {queries:[], directories:[], import_job_ids:[]}
  stats                  jsonb NOT NULL DEFAULT '{}',   -- {found, deduped, qualified, carded, agent_credits_used, contact_credits_used}
  approved_decision_id   uuid,
  started_by             uuid REFERENCES users(id),
  started_at             timestamptz,
  finished_at            timestamptz,
  created_at             timestamptz NOT NULL DEFAULT now(),
  updated_at             timestamptz NOT NULL DEFAULT now()
);
SELECT enable_tenant_rls('sourcing_runs');

CREATE TABLE candidates (
  id               uuid PRIMARY KEY,
  tenant_id        uuid NOT NULL REFERENCES tenants(id),
  sourcing_run_id  uuid REFERENCES sourcing_runs(id),
  account_id       uuid NOT NULL REFERENCES accounts(id),
  discovered_via   jsonb NOT NULL,              -- {kind: search|directory|import|signal|manual, query?, url?}
  status           text NOT NULL DEFAULT 'found'
                   CHECK (status IN ('found','deduped','enriching','qualifying','scored','carded','approved','rejected','snoozed','failed')),
  dedupe_reason    text CHECK (dedupe_reason IN ('existing_account','blocklisted','competitor','existing_buyer','recently_contacted','suppressed_domain')),
  scorecard_id     uuid,
  decision_id      uuid,
  created_at       timestamptz NOT NULL DEFAULT now(),
  updated_at       timestamptz NOT NULL DEFAULT now(),
  UNIQUE (tenant_id, sourcing_run_id, account_id)
);
SELECT enable_tenant_rls('candidates');
CREATE INDEX candidates_run_status ON candidates (tenant_id, sourcing_run_id, status);

CREATE TABLE evidence (
  id              uuid PRIMARY KEY,
  tenant_id       uuid NOT NULL REFERENCES tenants(id),
  account_id      uuid NOT NULL REFERENCES accounts(id),
  kind            text NOT NULL CHECK (kind IN ('web_page','search_result','tech_signal','import_field','provider_field','manual')),
  url             text,
  retrieved_at    timestamptz NOT NULL,
  snippet         text NOT NULL,                -- normalized text used for quote verification (≤ 4 KB)
  snapshot_ref    text,                         -- object storage key: tenant/<id>/evidence/<id>.txt.gz
  content_hash    bytea NOT NULL,               -- sha256(snippet)
  public_page_id  uuid,                         -- provenance only (no FK across global boundary)
  injection_flag  boolean NOT NULL DEFAULT false,
  created_at      timestamptz NOT NULL DEFAULT now()
);
SELECT enable_tenant_rls('evidence', false);
CREATE INDEX evidence_account ON evidence (tenant_id, account_id);

-- =============================================================================
-- 5. QUALIFICATION
-- =============================================================================

CREATE TABLE scorecards (
  id               uuid PRIMARY KEY,
  tenant_id        uuid NOT NULL REFERENCES tenants(id),
  candidate_id     uuid NOT NULL REFERENCES candidates(id),
  account_id       uuid NOT NULL REFERENCES accounts(id),
  playbook_id      uuid NOT NULL REFERENCES playbooks(id),
  playbook_version int  NOT NULL,
  total_score      int  NOT NULL,
  tier             text NOT NULL CHECK (tier IN ('A','B','C','D')),
  stopped_at       text,                        -- criterion key where knockout stopped evaluation
  summary          text,                        -- "why fit / risks"
  agent_run_id     uuid,
  agent_credits    int  NOT NULL DEFAULT 0,
  created_at       timestamptz NOT NULL DEFAULT now()
);
SELECT enable_tenant_rls('scorecards', false);
REVOKE UPDATE, DELETE ON scorecards FROM PUBLIC;      -- immutable

CREATE TABLE criterion_results (
  id            uuid PRIMARY KEY,
  tenant_id     uuid NOT NULL REFERENCES tenants(id),
  scorecard_id  uuid NOT NULL REFERENCES scorecards(id),
  criterion_id  uuid NOT NULL REFERENCES criteria(id),
  result        text NOT NULL CHECK (result IN ('pass','fail','unknown','skipped')),
  confidence    numeric(3,2) CHECK (confidence BETWEEN 0 AND 1),
  rationale     text,
  evidence_ids  uuid[] NOT NULL DEFAULT '{}',
  quotes        jsonb NOT NULL DEFAULT '[]',    -- [{evidence_id, text, verified: true}]
  points        int  NOT NULL DEFAULT 0,
  created_at    timestamptz NOT NULL DEFAULT now(),
  UNIQUE (scorecard_id, criterion_id)
);
SELECT enable_tenant_rls('criterion_results', false);
REVOKE UPDATE, DELETE ON criterion_results FROM PUBLIC;

-- =============================================================================
-- 6. CONTACT DATA LAYER (ADR-015)
-- =============================================================================

-- Global (no tenant_id). Accessible only to abcrm_global.
CREATE TABLE data_providers (
  id                      uuid PRIMARY KEY,
  key                     text NOT NULL UNIQUE,        -- e.g. 'provider_a'
  kind                    text NOT NULL CHECK (kind IN ('contact_finder','email_verifier','company_enrichment')),
  priority                int  NOT NULL,
  license                 jsonb NOT NULL,              -- {resale_ok, cache_scope: none|tenant|global, ttl_days, attribution}
  cost_per_lookup_micros  bigint NOT NULL DEFAULT 0,
  cost_per_hit_micros     bigint NOT NULL DEFAULT 0,
  status                  text NOT NULL CHECK (status IN ('active','disabled')),
  CHECK ((license->>'resale_ok')::boolean OR status = 'disabled'),
  updated_at              timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE licensed_contact_cache (
  id                   uuid PRIMARY KEY,
  provider_id          uuid NOT NULL REFERENCES data_providers(id),
  company_domain_ghmac bytea NOT NULL,
  person_key_ghmac     bytea NOT NULL,          -- HMAC(normalized name + domain)
  payload_enc          bytea NOT NULL,          -- encrypted with platform cache key
  fetched_at           timestamptz NOT NULL,
  expires_at           timestamptz NOT NULL,
  UNIQUE (provider_id, person_key_ghmac)
);
CREATE INDEX lcc_domain ON licensed_contact_cache (company_domain_ghmac, expires_at);

CREATE TABLE global_data_suppression (
  value_ghmac  bytea NOT NULL,
  kind         text NOT NULL CHECK (kind IN ('email','person_key','domain')),
  reason       text NOT NULL CHECK (reason IN ('opt_out','deletion_request','legal')),
  requested_at timestamptz NOT NULL,
  source       text NOT NULL,                  -- 'privacy_portal'|'email'|'drop'|'legal'
  PRIMARY KEY (kind, value_ghmac)
);

-- Tenant-scoped lookup log (billing + audit)
CREATE TABLE contact_lookups (
  id               uuid PRIMARY KEY,
  tenant_id        uuid NOT NULL REFERENCES tenants(id),
  account_id       uuid NOT NULL REFERENCES accounts(id),
  candidate_id     uuid REFERENCES candidates(id),
  titles           text[] NOT NULL,
  limit_n          int  NOT NULL,
  status           text NOT NULL CHECK (status IN ('reserved','running','completed','failed')),
  providers_tried  jsonb NOT NULL DEFAULT '[]',  -- [{provider_key, hits, cache_hit}]
  result_contact_ids uuid[] NOT NULL DEFAULT '{}',
  contact_credits  numeric(6,1) NOT NULL DEFAULT 0,
  created_at       timestamptz NOT NULL DEFAULT now(),
  updated_at       timestamptz NOT NULL DEFAULT now()
);
SELECT enable_tenant_rls('contact_lookups');

-- =============================================================================
-- 7. PUBLIC WEB (ADR-014) — global, no tenant attribution
-- =============================================================================

CREATE TABLE public_pages (
  id             uuid PRIMARY KEY,
  url_hash       bytea NOT NULL UNIQUE,        -- sha256(normalized url)
  url            text NOT NULL,
  domain         text NOT NULL,
  fetched_at     timestamptz NOT NULL,
  expires_at     timestamptz NOT NULL,
  status_code    int  NOT NULL,
  robots_allowed boolean NOT NULL,
  content_ref    text,                         -- object storage key (extracted text, gz)
  etag           text,
  last_modified  text
);
CREATE INDEX public_pages_domain ON public_pages (domain);

CREATE TABLE robots_cache (
  domain       text PRIMARY KEY,
  fetched_at   timestamptz NOT NULL,
  expires_at   timestamptz NOT NULL,
  rules        jsonb NOT NULL,                 -- parsed robots for our UA
  crawl_delay_ms int
);

CREATE TABLE crawl_policy (                    -- no-crawl list & per-domain overrides
  domain_pattern text PRIMARY KEY,             -- e.g. '*.linkedin.com'
  policy         text NOT NULL CHECK (policy IN ('deny','slow')),
  min_interval_ms int,
  reason         text NOT NULL
);
INSERT INTO crawl_policy VALUES
  ('linkedin.com','deny',NULL,'ToS — ADR-014/016'),
  ('*.linkedin.com','deny',NULL,'ToS — ADR-014/016'),
  ('facebook.com','deny',NULL,'login-walled'),
  ('*.facebook.com','deny',NULL,'login-walled');

CREATE TABLE global_contact_pressure (        -- Phase 2 (send guard); created now for schema stability
  domain_ghmac  bytea NOT NULL,
  window_start  date  NOT NULL,
  cold_sends    int   NOT NULL DEFAULT 0,
  PRIMARY KEY (domain_ghmac, window_start)
);

-- =============================================================================
-- 8. AGENTS & DECISIONS
-- =============================================================================

CREATE TABLE agent_templates (                 -- global, managed by ABCRM
  id             uuid PRIMARY KEY,
  key            text NOT NULL,                -- S1|S2|Q1|W1|...
  version        int  NOT NULL,
  definition     jsonb NOT NULL,               -- allowed_tools, configurable, limits, default_model_tier
  vertical_packs text[] NOT NULL DEFAULT '{}',
  eval_suite_ref text NOT NULL,
  status         text NOT NULL CHECK (status IN ('draft','published','deprecated')),
  published_at   timestamptz,
  UNIQUE (key, version)
);

CREATE TABLE agent_definitions (
  id                     uuid PRIMARY KEY,
  tenant_id              uuid NOT NULL REFERENCES tenants(id),
  lineage_id             uuid NOT NULL,
  template_key           text NOT NULL,
  template_version       int  NOT NULL,
  name                   text NOT NULL,
  version                int  NOT NULL,
  config                 jsonb NOT NULL,       -- triggers, filters, instructions_addendum, model_tier, extra_gates
  run_as                 jsonb NOT NULL,       -- {type: user|persona, id}
  status                 text NOT NULL CHECK (status IN ('active','paused','archived')),
  paused_reason          text CHECK (paused_reason IN ('manual','budget','anomaly','quality_breaker','entitlement','kill_switch')),
  credit_budget_daily    int,
  credit_budget_monthly  int,
  created_by             uuid REFERENCES users(id),
  created_at             timestamptz NOT NULL DEFAULT now(),
  updated_at             timestamptz NOT NULL DEFAULT now(),
  UNIQUE (tenant_id, lineage_id, version)
);
SELECT enable_tenant_rls('agent_definitions');

CREATE TABLE agent_runs (
  id                   uuid PRIMARY KEY,
  tenant_id            uuid NOT NULL REFERENCES tenants(id),
  agent_definition_id  uuid NOT NULL REFERENCES agent_definitions(id),
  agent_version        int  NOT NULL,
  trigger              jsonb NOT NULL,         -- {kind: event|schedule|user, event_id?, causation_id?}
  subject              jsonb,                  -- {type, id}
  status               text NOT NULL CHECK (status IN ('queued','running','waiting_decision','paused_quota','completed','failed','cancelled')),
  error                jsonb,
  tokens               jsonb NOT NULL DEFAULT '{}',   -- {input, output, cache_read, cache_write}
  cost_usd_micros      bigint NOT NULL DEFAULT 0,
  agent_credits        numeric(10,1) NOT NULL DEFAULT 0,
  trace_ref            text,
  started_at           timestamptz,
  finished_at          timestamptz,
  created_at           timestamptz NOT NULL DEFAULT now(),
  updated_at           timestamptz NOT NULL DEFAULT now()
);
SELECT enable_tenant_rls('agent_runs');
CREATE INDEX agent_runs_def ON agent_runs (tenant_id, agent_definition_id, created_at DESC);

CREATE TABLE agent_steps (
  id          uuid NOT NULL,
  tenant_id   uuid NOT NULL,
  run_id      uuid NOT NULL,
  seq         int  NOT NULL,
  kind        text NOT NULL CHECK (kind IN ('llm_call','tool_call','policy_eval')),
  name        text,                            -- model or tool name
  input_ref   text,                            -- object storage (redacted)
  output_ref  text,
  decision    text,                            -- for policy_eval: execute|propose|deny
  latency_ms  int,
  tokens      jsonb,
  created_at  timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (id, created_at)
) PARTITION BY RANGE (created_at);
SELECT enable_tenant_rls('agent_steps', false);

CREATE TABLE decisions (
  id                 uuid PRIMARY KEY,
  tenant_id          uuid NOT NULL REFERENCES tenants(id),
  gate_id            text NOT NULL CHECK (gate_id IN ('G-T1','G-T2','G-Q','G-OUT','G-M1','G-M2','G-B1','G-B2')),
  card_id            uuid,                     -- groups decisions approved together (G-Q + G-OUT)
  lane               text NOT NULL CHECK (lane IN ('hot','hot-intent','contact','standard','setup')),
  subject_type       text NOT NULL,            -- ipp|playbook|supply_profile|sourcing_run|account|...
  subject_id         uuid NOT NULL,
  proposed_by        jsonb NOT NULL,           -- {type: agent|user, agent_run_id?, user_id?}
  action             jsonb NOT NULL,           -- {tool, args}
  evidence           jsonb NOT NULL DEFAULT '{}',
  explanation        text,
  content_hash       bytea NOT NULL,           -- sha256(canonical JSON of action + rendered content)
  group_key          text,
  status             text NOT NULL DEFAULT 'pending'
                     CHECK (status IN ('pending','approved','edited','rejected','expired','superseded','executed','failed')),
  assignee_role      text,
  assignee_user_id   uuid REFERENCES users(id),
  sla_due_at         timestamptz,
  expires_at         timestamptz,
  decided_by         uuid REFERENCES users(id),
  decided_at         timestamptz,
  final_action       jsonb,                    -- when edited
  final_content_hash bytea,
  reject_reason_code text,
  reject_note        text,
  executed_at        timestamptz,
  created_at         timestamptz NOT NULL DEFAULT now(),
  updated_at         timestamptz NOT NULL DEFAULT now(),
  CHECK (status NOT IN ('approved','edited','rejected') OR (decided_by IS NOT NULL AND decided_at IS NOT NULL)),
  CHECK (status <> 'rejected' OR reject_reason_code IS NOT NULL),
  CHECK (status <> 'edited' OR (final_action IS NOT NULL AND final_content_hash IS NOT NULL))
);
SELECT enable_tenant_rls('decisions');
CREATE INDEX decisions_inbox ON decisions (tenant_id, status, lane, sla_due_at) WHERE status = 'pending';
CREATE INDEX decisions_subject ON decisions (tenant_id, subject_type, subject_id);
CREATE INDEX decisions_card ON decisions (tenant_id, card_id) WHERE card_id IS NOT NULL;
-- Exactly-once execution guard
CREATE UNIQUE INDEX decisions_executed_once ON decisions (id) WHERE status = 'executed';

-- First-email drafts attached to G-Q cards (sending is Phase 2)
CREATE TABLE email_drafts (
  id             uuid PRIMARY KEY,
  tenant_id      uuid NOT NULL REFERENCES tenants(id),
  account_id     uuid NOT NULL REFERENCES accounts(id),
  contact_id     uuid NOT NULL REFERENCES contacts(id),
  decision_id    uuid NOT NULL REFERENCES decisions(id),
  subject        text NOT NULL,
  body           text NOT NULL,
  ai_spans       jsonb NOT NULL DEFAULT '[]',  -- [{start, end}] AI-written spans to highlight
  content_hash   bytea NOT NULL,
  status         text NOT NULL DEFAULT 'proposed' CHECK (status IN ('proposed','approved','edited','rejected','queued','sent')),
  created_at     timestamptz NOT NULL DEFAULT now(),
  updated_at     timestamptz NOT NULL DEFAULT now()
);
SELECT enable_tenant_rls('email_drafts');

-- =============================================================================
-- 9. METERING (ADR-007, D28)
-- =============================================================================

CREATE TABLE usage_balances (
  tenant_id       uuid NOT NULL REFERENCES tenants(id),
  period          date NOT NULL,                -- first day of billing period
  meter           text NOT NULL CHECK (meter IN ('agent','contact')),
  included        numeric(12,1) NOT NULL,
  used            numeric(12,1) NOT NULL DEFAULT 0,
  overage_enabled boolean NOT NULL,
  spend_cap_usd   numeric(10,2),               -- NULL = no cap (enterprise only)
  overage_unit_price_usd numeric(10,6) NOT NULL,
  hard_stop       boolean NOT NULL,
  updated_at      timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (tenant_id, period, meter),
  CHECK (used >= 0)
);
SELECT enable_tenant_rls('usage_balances');

CREATE TABLE usage_events (
  id                   uuid NOT NULL,
  tenant_id            uuid NOT NULL,
  idempotency_key      text NOT NULL,          -- run:step:action
  occurred_at          timestamptz NOT NULL,
  meter                text NOT NULL CHECK (meter IN ('agent','contact')),
  action_type          text NOT NULL,          -- see pricing doc §1.1/1.2
  credits              numeric(10,1) NOT NULL, -- negative = release/refund
  agent_definition_id  uuid,
  agent_run_id         uuid,
  decision_id          uuid,
  sourcing_run_id      uuid,
  billable             boolean NOT NULL DEFAULT true,
  PRIMARY KEY (id, occurred_at),
  UNIQUE (tenant_id, idempotency_key, occurred_at)
) PARTITION BY RANGE (occurred_at);
SELECT enable_tenant_rls('usage_events', false);
REVOKE UPDATE, DELETE ON usage_events FROM PUBLIC;
-- NOTE: global idempotency across partitions is enforced by usage_idempotency below.
CREATE TABLE usage_idempotency (
  tenant_id        uuid NOT NULL,
  idempotency_key  text NOT NULL,
  created_at       timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (tenant_id, idempotency_key)
);
SELECT enable_tenant_rls('usage_idempotency', false);

CREATE TABLE agent_usage_daily (
  tenant_id            uuid NOT NULL REFERENCES tenants(id),
  agent_definition_id  uuid NOT NULL,
  date                 date NOT NULL,
  credits              numeric(10,1) NOT NULL DEFAULT 0,
  PRIMARY KEY (tenant_id, agent_definition_id, date)
);
SELECT enable_tenant_rls('agent_usage_daily', false);

CREATE TABLE cost_ledger (                     -- internal cost (not billed), for margin
  id               uuid NOT NULL,
  tenant_id        uuid NOT NULL,
  occurred_at      timestamptz NOT NULL,
  kind             text NOT NULL CHECK (kind IN ('llm','search','fetch','contact_provider','email_verify')),
  vendor           text NOT NULL,
  units            numeric(14,3) NOT NULL,      -- tokens, calls, lookups
  cost_usd_micros  bigint NOT NULL,
  agent_run_id     uuid,
  meter_link       text,                        -- idempotency_key of related usage_event
  PRIMARY KEY (id, occurred_at)
) PARTITION BY RANGE (occurred_at);
SELECT enable_tenant_rls('cost_ledger', false);

-- =============================================================================
-- 10. IMPORT (ADR-011)
-- =============================================================================

CREATE TABLE import_jobs (
  id           uuid PRIMARY KEY,
  tenant_id    uuid NOT NULL REFERENCES tenants(id),
  source       text NOT NULL CHECK (source IN ('csv','xlsx','hubspot','salesforce','lark')),
  purpose      text NOT NULL CHECK (purpose IN ('accounts','contacts','blocklist','existing_buyers','sourcing_candidates')),
  status       text NOT NULL CHECK (status IN ('uploaded','staged','mapping','pending_approval','dry_run','ready','committing','committed','rolled_back','failed')),
  file_ref     text,
  mapping_id   uuid,
  stats        jsonb NOT NULL DEFAULT '{}',
  created_by   uuid REFERENCES users(id),
  created_at   timestamptz NOT NULL DEFAULT now(),
  updated_at   timestamptz NOT NULL DEFAULT now()
);
SELECT enable_tenant_rls('import_jobs');

CREATE TABLE import_mappings (
  id           uuid PRIMARY KEY,
  tenant_id    uuid NOT NULL REFERENCES tenants(id),
  source       text NOT NULL,
  version      int  NOT NULL,
  object_map   jsonb NOT NULL,
  field_map    jsonb NOT NULL,
  transforms   jsonb NOT NULL DEFAULT '{}',
  approved_by  uuid REFERENCES users(id),
  approved_at  timestamptz,
  created_at   timestamptz NOT NULL DEFAULT now(),
  updated_at   timestamptz NOT NULL DEFAULT now()
);
SELECT enable_tenant_rls('import_mappings');

CREATE TABLE import_staging_rows (
  tenant_id     uuid NOT NULL,
  job_id        uuid NOT NULL,
  row_no        int  NOT NULL,
  source_object text,
  source_id     text,
  raw           jsonb NOT NULL,                 -- PII present: table purged 30 days after job end
  row_hash      bytea NOT NULL,
  status        text NOT NULL DEFAULT 'pending' CHECK (status IN ('pending','valid','warning','error','committed','skipped')),
  errors        jsonb NOT NULL DEFAULT '[]',
  target_type   text,
  target_id     uuid,
  PRIMARY KEY (tenant_id, job_id, row_no)
);
SELECT enable_tenant_rls('import_staging_rows', false);

CREATE TABLE external_ids (
  tenant_id      uuid NOT NULL,
  system         text NOT NULL,
  object         text NOT NULL,
  external_id    text NOT NULL,
  internal_type  text NOT NULL,
  internal_id    uuid NOT NULL,
  import_job_id  uuid,
  PRIMARY KEY (tenant_id, system, object, external_id)
);
SELECT enable_tenant_rls('external_ids', false);

-- =============================================================================
-- 11. OUTBOX, AUDIT, HISTORY
-- =============================================================================

CREATE TABLE outbox (
  id            uuid PRIMARY KEY,
  tenant_id     uuid NOT NULL,
  topic         text NOT NULL,                  -- see events.md
  payload       jsonb NOT NULL,                 -- IDs only, no PII
  causation_id  uuid,
  correlation_id uuid,
  created_at    timestamptz NOT NULL DEFAULT now(),
  dispatched_at timestamptz
);
SELECT enable_tenant_rls('outbox', false);
CREATE INDEX outbox_pending ON outbox (created_at) WHERE dispatched_at IS NULL;

CREATE TABLE audit_log (
  id          uuid NOT NULL,
  tenant_id   uuid NOT NULL,
  at          timestamptz NOT NULL DEFAULT now(),
  actor       jsonb NOT NULL,                   -- {type, id, on_behalf_of?}
  action      text NOT NULL,                    -- e.g. 'decision.approved'
  subject     jsonb NOT NULL,                   -- {type, id}
  before_ref  text,
  after_ref   text,
  prev_hash   bytea,
  hash        bytea NOT NULL,                   -- sha256(prev_hash || canonical(row))
  PRIMARY KEY (id, at)
) PARTITION BY RANGE (at);
SELECT enable_tenant_rls('audit_log', false);
REVOKE UPDATE, DELETE ON audit_log FROM PUBLIC;

CREATE TABLE record_changes (
  id            uuid PRIMARY KEY,
  tenant_id     uuid NOT NULL,
  record_type   text NOT NULL,
  record_id     uuid NOT NULL,
  field         text NOT NULL,
  old_value     jsonb,
  new_value     jsonb,
  actor_type    text NOT NULL CHECK (actor_type IN ('user','agent','integration','system')),
  actor_id      text NOT NULL,
  agent_run_id  uuid,
  created_at    timestamptz NOT NULL DEFAULT now()
);
SELECT enable_tenant_rls('record_changes', false);
CREATE INDEX record_changes_record ON record_changes (tenant_id, record_type, record_id, created_at DESC);

